/* * @lc app=leetcode id=1600 lang=kotlin * * [1600] Throne Inheritance */ class ThroneInheritance(val kingName: String, val children: MutableMap<String, MutableList<String>> = mutableMapOf(), val dead: MutableSet<String> = mutableSetOf()) { fun birth(parentName: String, childName: String) = children.getOrPut(parentName) { mutableListOf() }.add(childName).let { } fun death(name: String) = dead.add(name).let { } fun getInheritanceOrder(): List<String> = mutableListOf<String>().also { res -> kotlin.DeepRecursiveFunction<String, Unit> { u -> run { if (u !in dead) res.add(u) }.let { children[u]?.forEach { callRecursive(it) } } }(kingName) } }